{
  "part": {
    "name": "Lever bar with tube boss and rounded end",
    "description": "Single solid consisting of a long rectangular bar (constant thickness) with a rounded left-end perimeter and a vertical cylindrical tube boss blended into the bar near the left side. Boss contains a blind cylindrical bore.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Approximately symmetric about the bar mid-thickness plane (z=4 in STEP report) and about the boss center plane through z=4; not symmetric along length (x) due to boss location and one rounded end."
  },
  "Section": [
    {
      "id": "S1",
      "name": "Main bar body",
      "features included": [
        "Primary load-bearing bar/lever beam",
        "Flat top and bottom datum planes",
        "Long side walls (one side partially interrupted near boss blend and rounded end)",
        "Square right end face (terminal interface/stop face)"
      ],
      "function intent": "Provide the primary structural span for applying/transmitting bending and shear loads between the boss region and the distal right end; provide flat reference surfaces for assembly or clearance.",
      "physical behavior": "Acts as a rectangular beam: resists bending about its long axis and torsion; distributes stress from the boss blend region along the length; flat faces provide stable contact/clearance boundaries.",
      "geometry": "Prismatic rectangular bar: length ~105 mm (x -25 to 80), width ~12 mm (y 11 to 23), thickness ~4 mm (z 2 to 6). One long side (y=23) is split due to local transitions near the boss and rounded end.",
      "location": "Extends along the full x-span of the part; forms the base under the boss and continues to the right square end.",
      "colour": {
        "R": 210,
        "G": 120,
        "B": 60
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Bottom face (bar underside)",
          "Brep_id": "FACE 1",
          "description": "Large planar underside of bar at z=2, spanning most of the part length/width."
        },
        {
          "face_code": "0001",
          "name": "Top face (bar topside)",
          "Brep_id": "FACE 6",
          "description": "Large planar topside of bar at z=6, spanning most of the part length/width (interrupted by boss blend boundary)."
        },
        {
          "face_code": "0002",
          "name": "Long side face A",
          "Brep_id": "FACE 5",
          "description": "Planar long side wall at y=11 (one full-length side of the bar)."
        },
        {
          "face_code": "0003",
          "name": "Long side face B (main segment)",
          "Brep_id": "FACE 8",
          "description": "Planar long side wall at y=23 over the main span (x≈6.6 to 80); truncated near boss/rounded-end transitions."
        },
        {
          "face_code": "0004",
          "name": "Right end face",
          "Brep_id": "FACE 7",
          "description": "Planar terminal face at x=80 closing the bar end."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 2"
      ],
      "relationships": [
        {
          "source id": "S1",
          "target id": "S2",
          "function relationship": "provides_clearance",
          "structural relationship": "blends_into"
        },
        {
          "source id": "S1",
          "target id": "S3",
          "function relationship": "distributes_stress",
          "structural relationship": "attached_to"
        }
      ]
    },
    {
      "id": "S2",
      "name": "Rounded left end perimeter",
      "features included": [
        "Rounded/semicircular end contour for the bar",
        "Edge-round transition improving clearance and reducing stress concentration at the end"
      ],
      "function intent": "Provide a rounded end for clearance/handling and to reduce stress concentration compared to a sharp square end; define a smooth external envelope at the left extremity.",
      "physical behavior": "Reduces peak stress by removing sharp corner; provides a continuous curved boundary that can slide/clear adjacent parts more easily than a square corner.",
      "geometry": "Cylindrical perimeter surface forming the bar’s left-end rounding (cylinder axis along z in STEP; radius ~17.5). Connects into the bar’s planar side and top/bottom faces.",
      "location": "Left extremity of the bar near x=-25, forming the rounded end of the overall part.",
      "colour": {
        "R": 70,
        "G": 160,
        "B": 210
      },
      "major_faces": [
        {
          "face_code": "0005",
          "name": "Left-end rounded perimeter surface",
          "Brep_id": "FACE 0",
          "description": "Cylindrical curved outer surface (R=17.5) forming the rounded contour of the bar end."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S2",
          "target id": "S1",
          "function relationship": "provides_clearance",
          "structural relationship": "attached_to"
        }
      ]
    },
    {
      "id": "S3",
      "name": "Boss-to-bar blend pad",
      "features included": [
        "Smooth blend/fillet-like transition between tube boss and bar",
        "Stress-relief geometry at the boss root"
      ],
      "function intent": "Reinforce the joint between the boss and the bar and reduce stress concentration at the boss root under bending/torque loads applied through the boss.",
      "physical behavior": "Spreads load from the boss into the bar over a larger area; reduces local bending stress and improves fatigue resistance by smoothing curvature transitions.",
      "geometry": "Single BSPLINE transition surface forming a smooth saddle/dome between the boss outer cylinder and the bar top/side region.",
      "location": "At the base of the tube boss where it meets the bar, centered around the boss footprint.",
      "colour": {
        "R": 120,
        "G": 190,
        "B": 90
      },
      "major_faces": [
        {
          "face_code": "0006",
          "name": "Boss root blend surface",
          "Brep_id": "FACE 9",
          "description": "BSPLINE blended surface connecting bar surfaces to the boss base (primary stress-distributing transition)."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S3",
          "target id": "S1",
          "function relationship": "distributes_stress",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S3",
          "target id": "S4",
          "function relationship": "transmits_load",
          "structural relationship": "blends_into"
        }
      ]
    },
    {
      "id": "S4",
      "name": "Tube boss with blind bore",
      "features included": [
        "Cylindrical outer boss (mounting/locating feature)",
        "Blind cylindrical bore (socket/interface)",
        "Top annular rim face (opening plane)",
        "Internal bore bottom face (blind end stop)"
      ],
      "function intent": "Provide a vertical socket/mounting interface to locate and constrain a mating cylindrical component (e.g., pin/shaft/handle), with a blind stop to set insertion depth.",
      "physical behavior": "Outer cylinder carries hoop/bearing loads and transfers moments into the blend pad; inner bore guides and constrains the mating part (radial constraint) and the bore bottom provides axial stop reaction.",
      "geometry": "Coaxial outer and inner cylinders along the boss axis (STEP axis along y). Outer radius ~7, inner radius ~5; top opening at y=34; blind bore bottom at y=25; outer cylinder extends down to ~y=24 before blending.",
      "location": "Near the left side of the bar (around x=0, z=4 in STEP), rising upward from the bar via the blend pad.",
      "colour": {
        "R": 160,
        "G": 90,
        "B": 200
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Boss outer cylindrical surface",
          "Brep_id": "FACE 10",
          "description": "Outer cylinder of boss (R=7) providing the external boss wall."
        },
        {
          "face_code": "0008",
          "name": "Top annular opening face",
          "Brep_id": "FACE 11",
          "description": "Planar top face at y=34 forming the annular rim around the bore opening."
        },
        {
          "face_code": "0009",
          "name": "Inner bore cylindrical surface",
          "Brep_id": "FACE 3",
          "description": "Inner cylindrical bore wall (R=5) guiding/locating the mating cylindrical part."
        },
        {
          "face_code": "0010",
          "name": "Bore bottom (blind stop) face",
          "Brep_id": "FACE 4",
          "description": "Planar circular face at y=25 closing the bore (insertion depth stop)."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S4",
          "target id": "S3",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to"
        },
        {
          "source id": "S4",
          "target id": "S1",
          "function relationship": "mounts_to",
          "structural relationship": "supports"
        }
      ]
    }
  ]
}
